param([string]$Phase='red',[string]$Action='all')
$ErrorActionPreference='Stop'
. "$PSScriptRoot/iam-model-local-meter-watchdog-review-fix-wait.ps1"
$root=$script:WatchdogRoot;$base="$root/.local/iam-model-frozen-prompt";$epoch="$base/$Phase-runtime"
$java='C:/Program Files/Eclipse Adoptium/jdk-21.0.12.8-hotspot/bin/java.exe'
$env:JAVA_HOME=Split-Path (Split-Path $java);$env:Path="$env:JAVA_HOME/bin;$env:Path"
$cpModel=(Get-Content -Raw "$root/.local/iam-model-egress-local-meter/model-classpath.txt").Replace('\','/').Trim()
$cpEngine=(Get-Content -Raw "$root/.local/iam-model-egress-local-meter/engine-classpath.txt").Replace('\','/').Trim()
$tls="$root/.local/iam-model-input-producer/tls/engine.p12";$trust="$root/.local/iam-model-input-producer/tls/trust.p12"
$mavenHome=Split-Path (Split-Path (Get-Command mvn.cmd).Source)
$boot=(Get-ChildItem -LiteralPath "$mavenHome/boot" -Filter 'plexus-classworlds-*.jar').FullName.Replace('\','/')
function ArgsFile($Name,$Items){
 $path="$root/.tools/iam-model-frozen-prompt-$Phase-$Name.args"
 $quoted=$Items|ForEach-Object {'"'+($_.Replace('\','/').Replace($root,'V:').Replace('"','\"'))+'"'}
 [IO.File]::WriteAllLines($path,$quoted,[Text.UTF8Encoding]::new($false));return $path
}
function Check($r){if($r.timedOut -or $r.exit -ne 0){throw "CHILD_FAILED_TIMEOUT_$($r.timedOut)_EXIT_$($r.exit)"}}
function Maven($Name,$Goals){
 $argsFile=ArgsFile $Name (@('-classpath',$boot,"-Dclassworlds.conf=$mavenHome/bin/m2.conf","-Dmaven.home=$mavenHome","-Dmaven.multiModuleProjectDirectory=$root",'org.codehaus.plexus.classworlds.launcher.Launcher','-o','-B','-ntp')+$Goals+@('-Dmaven.repo.local=.tools/m2','-Dproject.build.sourceEncoding=UTF-8','-Dmaven.compiler.encoding=UTF-8','-Djdk.net.unixdomain.tmpdir=V:/.local/tmp'))
 return Invoke-OwnBoundedProcess $java @('@'+$argsFile.Replace($root,'V:')) 'maven-launcher' "$base/$Phase-$Name" 30
}
if($Action -eq 'compile'){
 Check (Maven 'compile' @('-pl','admin-common,model-gateway,engine-runtime','-am','test-compile','-DskipTests'));exit
}
if(Test-Path $epoch){throw 'FRESH_EPOCH_REQUIRED'}
New-Item -ItemType Directory $epoch,"$epoch/setup","$epoch/model","$epoch/engine"|Out-Null
$acl=icacls $epoch /inheritance:r /grant:r 'Administrator:(OI)(CI)F' 'SYSTEM:(OI)(CI)F';$ac=$LASTEXITCODE
Write-OwnJson "$epoch/acl.json" @{exit=$ac;output=@($acl);protected=(Get-Acl $epoch).AreAccessRulesProtected;at=[DateTime]::UtcNow.ToString('O')}
if($ac -ne 0 -or !(Get-Acl $epoch).AreAccessRulesProtected){throw 'ACL_REQUIRED_BEFORE_PRIVATE_WRITES'}
New-Item -ItemType Directory "$base/helper-classes" -Force|Out-Null
$helperCp="$base/helper-classes;$cpModel";$fixtures=[Collections.Generic.List[object]]::new()
function StartFixture($Name,$Items,$Ready){
 $argfile=ArgsFile $Name $Items;$guard=[ReviewOwnedDeadline]::new(30)
 try {
  $p=Start-Process $java -ArgumentList ('@'+$argfile.Replace($root,'V:')) -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput "$epoch/$Name.stdout.log" -RedirectStandardError "$epoch/$Name.stderr.log" -PassThru
  $r=Register-OwnProcess $p "$Name-fixture";if(!$r){throw 'FIXTURE_IDENTITY_REQUIRED'}
  $fixtures.Add($r);$guard.Add($p,$r.startTicks)
  Write-OwnJson "$epoch/$Name-command.json" @{executable=$java;argfile=$argfile;arguments=@('@'+$argfile.Replace($root,'V:'));cwd=$root;pid=$r.pid;startTicks=$r.startTicks;at=[DateTime]::UtcNow.ToString('O')}
  while(!(Test-Path $Ready)){if(!(Test-OwnAlive $r) -or $guard.Fired){throw 'READINESS_FAILED_LE30'};$p.WaitForExit(50)|Out-Null}
  return $r
 }finally{$guard.Dispose();Write-OwnJson "$epoch/$Name-readiness.json" @{timerDisposedAndCallbacksCompleted=$true;fired=$guard.Fired;at=[DateTime]::UtcNow.ToString('O')}}
}
$failure=$null;$cleanup=[Collections.Generic.List[string]]::new()
try {
 $compile=ArgsFile 'helper-compile' @('-encoding','UTF-8','-cp',$cpModel,'-d',"$base/helper-classes","$root/.tools/iam-model-frozen-prompt-resources.java")
 Check (Invoke-OwnBoundedProcess ($env:JAVA_HOME+'/bin/javac.exe') @('@'+$compile.Replace($root,'V:')) 'helper-compile' "$epoch/helper-compile" 30)
 $env:AGENT_DB_PASSWORD=(((Get-Content -LiteralPath "$root/.env"|Where-Object {$_ -match '^AGENT_DB_PASSWORD='}) -split '=',2)[1]).Trim('"',"'")
 $setupArgs=ArgsFile 'setup' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dbinding.fixture=$epoch/setup","-Dwatchdog.base=$base",'-cp',$helperCp,'IamModelFrozenPromptResources','setup')
 Check (Invoke-OwnBoundedProcess $java @('@'+$setupArgs.Replace($root,'V:')) 'own-db-setup' "$epoch/setup-run" 30)
 Remove-Item Env:AGENT_DB_PASSWORD
 Copy-Item "$epoch/setup/model-db.json" "$epoch/model/model-db.json";Copy-Item "$epoch/setup/engine-db.json" "$epoch/engine/engine-db.json"
 foreach($item in Get-ChildItem Env:|Where-Object {$_.Name -match '^AGENT_(DB|SECRET|IAM|ENGINE|MODEL)'}){Remove-Item -LiteralPath "Env:$($item.Name)"}
 Write-OwnJson "$epoch/child-env-names.json" @{removedUnrelatedServiceSecrets=$true;remainingAgentNames=@((Get-ChildItem Env:|Where-Object {$_.Name -like 'AGENT_*'}).Name)}
 $seed=StartFixture 'seed' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dbinding.fixture=$epoch/model","-Dconsumer.tls=$tls","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only','-cp',$cpModel,'cn.agentplatform.model.application.FrozenInitialInputMeterFixture','serve') "$epoch/model/model-seed-ready.json"
 Copy-Item "$epoch/model/binding.json" "$epoch/engine/binding.json"
 $engine=StartFixture 'engine' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dconsumer.fixture=$epoch/engine","-Dconsumer.tls=$tls","-Dconsumer.source.sha=$((Get-FileHash "$base/$Phase-source/source.json").Hash.ToLower())","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only','-cp',$cpEngine,'cn.agentplatform.engine.infra.FrozenModelBindingProducerFixture') "$epoch/engine/ready.json"
 foreach($file in @('ready.json','request.json','manifest.json','model-config.json','model-secret.txt','first-ticket.txt','repeat-ticket.txt','newGrant-ticket.txt','wrongOwner-ticket.txt','wrongRoot-ticket.txt','differentOrigin-ticket.txt')){Copy-Item "$epoch/engine/$file" "$epoch/model/$file"}
 $env:AGENT_SECRET_IAM_MODEL_CLIENT=Get-Content -Raw "$epoch/model/model-secret.txt"
 $groups=Get-Content -Raw "$base/$Phase-groups.json"|ConvertFrom-Json
 foreach($group in $groups){
  $dest="$epoch/group-$($group.id)";New-Item -ItemType Directory $dest|Out-Null
  Write-OwnJson "$dest/selection.json" $group
  $r=Maven "group-$($group.id)" @('-pl','admin-common,model-gateway,engine-runtime','-am','test',"-Dtest=$($group.selector)",'-Dsurefire.failIfNoSpecifiedTests=false',"-Dbinding.fixture=$epoch/model","-Dconsumer.fixture=$epoch/model","-Dconsumer.tls=$tls","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only')
  & python "$root/.tools/iam-model-frozen-prompt-capture.py" group $Phase $group.id
  if($LASTEXITCODE -ne 0){throw 'XML_CAPTURE_FAILED'}
  if($Phase -ne 'red'){Check $r}
  if($r.timedOut){throw 'MAVEN_TIMED_OUT'}
  Write-Output "GROUP $($group.id) EXIT $($r.exit) ELAPSED $($r.elapsedMs)"
 }
 if($Phase -eq 'final'){& python "$root/.tools/iam-model-frozen-prompt-capture.py" finite $Phase;if($LASTEXITCODE -ne 0){throw 'FINITE_CAPTURE_FAILED'}}
}catch{$failure=$_}finally{
 foreach($n in @('AGENT_DB_PASSWORD','AGENT_SECRET_IAM_MODEL_CLIENT')){if(Test-Path "Env:$n"){Remove-Item "Env:$n"}}
 try {
  if($engine){[IO.File]::WriteAllText("$epoch/engine/stop",'stop')};if($seed){[IO.File]::WriteAllText("$epoch/model/model-stop",'stop')}
  $stop=[Diagnostics.Stopwatch]::StartNew();foreach($f in $fixtures){if(Test-OwnAlive $f){$f.process.WaitForExit([Math]::Max(0,10000-[int]$stop.ElapsedMilliseconds))|Out-Null}}
  Write-OwnJson "$epoch/fixture-closure.json" @{gracefulWaitMs=$stop.ElapsedMilliseconds;cleanup=(Stop-OwnProcesses $fixtures)}
 }catch{$cleanup.Add($_.Exception.Message)}
 try {
  Write-OwnJson "$epoch/pre-db-process-closure.json" (Stop-OwnProcesses $script:OwnedProcesses)
  if(Test-Path "$base/databases.jsonl"){
   $env:AGENT_DB_PASSWORD=(((Get-Content -LiteralPath "$root/.env"|Where-Object {$_ -match '^AGENT_DB_PASSWORD='}) -split '=',2)[1]).Trim('"',"'")
   try{$close=ArgsFile 'close' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dbinding.fixture=$epoch/setup","-Dwatchdog.base=$base",'-cp',$helperCp,'IamModelFrozenPromptResources','close');Check (Invoke-OwnBoundedProcess $java @('@'+$close.Replace($root,'V:')) 'own-db-close' "$epoch/close-run" 30)}finally{Remove-Item Env:AGENT_DB_PASSWORD}
  }
 }catch{$cleanup.Add($_.Exception.Message)}finally{
  Write-OwnJson "$epoch/all-process-closure.json" @{cleanup=(Stop-OwnProcesses $script:OwnedProcesses);identities=@($script:OwnedProcesses|ForEach-Object {@{pid=$_.pid;startTicks=$_.startTicks;role=$_.role;parent=$_.parent;alive=Test-OwnAlive $_}});at=[DateTime]::UtcNow.ToString('O')}
 }
 Write-OwnJson "$epoch/coordinator-result.json" @{primaryFailure=if($failure){$failure.Exception.Message}else{$null};cleanupFailures=$cleanup.ToArray();passed=(!$failure -and $cleanup.Count -eq 0)}
}
if($failure){throw $failure};if($cleanup.Count){throw ($cleanup -join ',')}

