$env:GIT_CONFIG_NOSYSTEM='1';$env:GIT_CONFIG_GLOBAL='NUL';$env:GIT_CONFIG_SYSTEM='NUL'
function Git($Name,$Directory,$Items){
 $r=Invoke-OwnBoundedProcess 'C:/Program Files/Git/cmd/git.exe' (@('-C',$Directory,'-c','core.autocrlf=false','-c','core.safecrlf=false','-c','core.whitespace=cr-at-eol','-c','core.quotepath=false','-c','core.fsmonitor=false')+$Items) 'own-native-git' "$base/native/$Name" 30
 if($r.timedOut -or $r.exit -ne 0){throw "NATIVE_FAILED_$Name"}
}
Git 'init-diff-batched' "$native/diff" @('init','--quiet')
